INSERT INTO `v1_2a64ebcfef4f6ccb06254fe125f202fd07788de414b2bbec46b7e597e9b43ce4` VALUES (1, "ＴＰ回復や行動速度アップにより、キャラのスキルやユニオンバーストの発動数が増加する\n", "加速", "【加速】");
INSERT INTO `v1_2a64ebcfef4f6ccb06254fe125f202fd07788de414b2bbec46b7e597e9b43ce4` VALUES (2, "敵に継続ダメージ系状態異常や弱体効果を付与し、敵を弱体化させる\n", "弱体", "【弱体】");
INSERT INTO `v1_2a64ebcfef4f6ccb06254fe125f202fd07788de414b2bbec46b7e597e9b43ce4` VALUES (3, "クリティカルや通常攻撃強化により、攻撃性能を強化する\n", "会心", "【会心】");
INSERT INTO `v1_2a64ebcfef4f6ccb06254fe125f202fd07788de414b2bbec46b7e597e9b43ce4` VALUES (4, "攻撃力や防御力アップのバフ効果を用いて、キャラを強化する\n", "強化", "【強化】");
INSERT INTO `v1_2a64ebcfef4f6ccb06254fe125f202fd07788de414b2bbec46b7e597e9b43ce4` VALUES (5, "ＨＰアップやバリア展開により、耐久性能を強化する\n", "守備", "【守備】");
